To design an AI agent that plays Connect Four, we'll use a combination of game theory (minimax algorithm, in this case) and heuristics. The minimax algorithm works by predicting future sequences of moves and assumes that the players will always make the best possible move at each step. Here's a simplified version of how you might implement such an agent:

```python
import numpy as np
import copy

EMPTY = 0
PLAYER_X = 1
PLAYER_O = 2

ROWS = 6
COLUMNS = 7

class Agent_AI:
    def __init__(self, player):
        self.player = player
        if self.player == PLAYER_X:
            self.opponent = PLAYER_O
        else:
            self.opponent = PLAYER_X

    def ai_move(self, board):
        newBoard = copy.deepcopy(board)
        best_val = -np.inf
        best_column = np.random.choice([c for c in range(COLUMNS)])

        for column in range(COLUMNS):
            if newBoard[0][column] == EMPTY: 
                row = self.drop_piece(newBoard, column, self.player)
                score = self.minimax(newBoard, 0, False)
                newBoard[row][column] = EMPTY
                if score > best_val:
                    best_val = score
                    best_column = column

        return best_column

    def drop_piece(self, board, col, piece):
        for row in range(ROWS-1, -1, -1):
            if board[row][col] == EMPTY:
                board[row][col] = piece
                return row

    def minimax(self, board, depth, isMaximizingPlayer):
        if self.game_over(board) or depth == 0:
            return self.evaluate_board(board)

        newBoard = copy.deepcopy(board)
        if isMaximizingPlayer:
            value = -np.inf
            for column in range(COLUMNS):
                if newBoard[0][column] == EMPTY: 
                    row = self.drop_piece(newBoard, column, self.player)
                    value = max(value, self.minimax(newBoard, depth - 1, False))
                    newBoard[row][column] = EMPTY
            return value

        else: 
            value = np.inf
            for column in range(COLUMNS):
                if newBoard[0][column] == EMPTY: 
                    row = self.drop_piece(newBoard, column, self.opponent)
                    value = min(value, self.minimax(newBoard, depth - 1, True))
                    newBoard[row][column] = EMPTY
            return value

    def game_over(self, board):
