class Cube:
    def __init__(self, dimensions):
        self.dimensions = dimensions

    def draw(self, angle):
        os.system('cls' if os.name == 'nt' else 'clear')  # Clear the console

        print(''.join([
            self.get_pixel(x, y, angle)
            for y in range(self.dimensions)
            for x in range(self.dimensions)
        ]))

    def get_pixel(self, x, y, angle):
        z = self.get_z(x, y, angle)

        if z <= 0 or z >= self.dimensions:
            return ' '  # Don't draw anything if the z-coordinate is out of bounds

        if x == 0 or x == self.dimensions - 1 or y == 0 or y == self.dimensions - 1 or z == 1 or z == self.dimensions - 1:
            return '#'  # Draw a border

        return ' '  # Fill the center with blank space

    def get_z(self, x, y, angle):
        # Rotate the x and y coordinates around the center of the cube
        x, y = x - self.dimensions / 2, y - self.dimensions / 2
        x, y = x * np.cos(angle) - y * np.sin(angle), x * np.sin(angle) + y * np.cos(angle)
        x, y = x + self.dimensions / 2, y + self.dimensions / 2

        # Return the z-coordinate
        return int(self.dimensions / 2 - np.sqrt((x - self.dimensions / 2) ** 2 + (y - self.dimensions / 2) ** 2))


