import numpy as np

def create_array():
    while True:
        try:
            row = int(input("Enter the number of rows: "))
            col = int(input("Enter the number of columns: "))
            if row > 0 and col > 0:
                return np.zeros((row, col))
            else:
                print("Error: Inputs must be greater than 0. Please try again.")
        except ValueError:
            print("Error: Invalid input. Please enter integer values.")

def resize_array(array):
    while True:
        try:
            row = int(input("Enter the new number of rows: "))
            col = int(input("Enter the new number of columns: "))
            if row > 0 and col > 0:
                return np.resize(array, (row, col))
            else:
                print("Error: Inputs must be greater than 0. Please try again.")
        except ValueError:
            print("Error: Invalid input. Please enter integer values.")

# Usage:

